 IF EXISTS (SELECT 1 FROM public.auto_campaign_action_detail_statuses t JOIN jsonb_to_recordset($descriptions$[{"id":1,"description":"Loại chiến dịch: sms_send. Phạm vi: mọi hành động của loại chiến dịch (action_code=NULL). Trạng thái: thành công. Runtime ghi nhận hành động hoàn tất thành công theo hợp đồng của hành động; không tự suy ra người nhận đã đọc, email đã vào inbox hoặc lời mời đã được chấp nhận. Nhóm ngữ nghĩa auto_status.id=20; không thay thế điều kiện status_value/action_code. Đây là danh mục lựa chọn Automation, không chứng minh đã có lượt chạy phát ra trạng thái. So khớp status_value không phân biệt hoa/thường; action_code NULL là wildcard. Dòng có sẵn trước v347, giữ nguyên ID/điều kiện/trạng thái. Không giả định chuỗi lịch sử còn được mọi phiên bản runtime phát ra. Mô tả cho agent, không điều khiển runtime."},{"id":2,"description":"Loại chiến dịch: sms_send. Phạm vi: mọi hành động của loại chiến dịch (action_code=NULL). Trạng thái: thất bại. Runtime ghi nhận hành động không hoàn tất thành công; nguyên nhân nằm trong detail/log/error_code. Không tự suy ra có thể retry. Nhóm ngữ nghĩa auto_status.id=21; không thay thế điều kiện status_value/action_code. Đây là danh mục lựa chọn Automation, không chứng minh đã có lượt chạy phát ra trạng thái. So khớp status_value không phân biệt hoa/thường; action_code NULL là wildcard. Dòng có sẵn trước v347, giữ nguyên ID/điều kiện/trạng thái. Không giả định chuỗi lịch sử còn được mọi phiên bản runtime phát ra. Mô tả cho agent, không điều khiển runtime."},{"id":3,"description":"Loại chiến dịch: sms_send. Phạm vi: mọi hành động của loại chiến dịch (action_code=NULL). Trạng thái: lỗi. Runtime ghi nhận lỗi khi xử lý hành động; đây là trạng thái detail, không phải mã err_* hay chỉ thị retry/khóa tài khoản. Nhóm ngữ nghĩa auto_status.id=22; không thay thế điều kiện status_value/action_code. Đây là danh mục lựa chọn Automation, không chứng minh đã có lượt chạy phát ra trạng thái. So khớp status_value không phân biệt hoa/th