 'access',(SELECT jsonb_build_object('owner',pg_get_userbyid(relowner),'acl',relacl,'rls',relrowsecurity,'force_rls',relforcerowsecurity) FROM pg_class WHERE oid='public.auto_campaign_action_detail_statuses'::regclass),
 'sequence_definition',(SELECT to_jsonb(s)-'last_value' FROM pg_sequences s WHERE schemaname='public' AND sequencename='auto_campaign_action_detail_statuses_id_seq')),'{columns}',(SELECT jsonb_agg(c ORDER BY (c->>'position')::int) FROM jsonb_array_elements((jsonb_build_object(
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'comment',col_description(a.attrelid,a.attnum)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.auto_campaign_action_detail_statuses'::regclass AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conname) FROM pg_constraint WHERE conrelid='public.auto_campaign_action_detail_statuses'::regclass),
 'incoming_foreign_keys',(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conname) FROM pg_constraint WHERE confrelid='public.auto_campaign_action_detail_statuses'::regclass),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef) ORDER BY indexname) FROM pg_indexes WHERE schemaname='public' AND tablename='auto_campaign_action_detail_statuses'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('name',tgname,'definition',pg_get_triggerdef(oid)) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='public.auto_campaign_action_detail_statuses'::regclass AND NOT tgisinternal),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY policyname) FROM pg_policies p WHERE schemaname='public' AND tablename='auto_campaign_action_detail_statuses'),
 'access',(SELECT jsonb_build_object('owner',pg_get_userbyid(relowner),'acl',relacl,'rls',relrowsecurity,'force_rls',relforcerowsecurity) FROM pg_class WHERE oid='public.auto_campaign_action_detail_statuses'::regclass),
 'sequence_definition',(SELECT to_jsonb(s)-'last_value' FROM pg_sequences s WHERE schemaname='public' AND sequencename='auto_campaign_action_detail_statuses_id_seq')))->'columns') c WHERE c->>'name'<>'description')))::text)<>'1677fe7321ea46afe0f1f232ec3367ad' THEN RAISE EXCEPTION 'v347 rollback: base schema changed'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.auto_campaign_action_detail_statuses'::regclass AND a.attname='description' AND NOT a.attisdropped AND a.atttypid='text'::regtype AND a.attnotnull AND pg_get_expr(d.adbin,d.adrelid)='''Danh mục trạng thái chi tiết chiến dịch, không phải policy lỗi hay lịch sử một lần chạy. Đọc campaign_action_id để biết loại chiến dịch; action_code NULL nghĩa là mọi hành động trong loại đó, có giá trị nghĩa là chỉ hành động đó. status_value được so khớp không phân biệt hoa/thường; label chỉ để hiển thị. status_id NULL nghĩa là chưa gắn nhóm ngữ nghĩa auto_status, không phải dữ liệu hỏng. Không suy ra thành công, retry, khóa tài khoản hoặc kết quả gửi/nhận từ việc có dòng danh mục; đối chiếu detail/log và runtime. Dòng có thể được seed, lưu từ Automation hoặc tự sinh khi runtime ghi detail. Mô tả chỉ phục vụ agent, không tham gia điều kiện chạy.''::text' AND col_description(a.attrelid,a.attnum)='Agent-readable documentation only. Not executed or used for Automation matching. New auto-generated rows inherit a generic explanation; curated rows have contextual descriptions. NULL action_code is a wildcard, NULL status_id means no semantic group.') THEN RAISE EXCEPTION 'v347 rollback: description schema changed'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(expected) e LEFT JOIN public.auto_campaign_action_detail_statuses t ON t.id=(e->>'id')::bigint WHERE t.id IS NULL OR md5(to_jsonb(t)::text)<>e->>'md5' OR t.campaign_action_id<>e->>'campaign_action_id' OR t.action_code IS DISTINCT FROM e->>'action_code' OR t.status_value<>e->>'status_value') THEN RAISE EXCEPTION 'v347 rollback: inserted row changed or missing'; END IF;
